/**
 * Block metadata as received _from_ the Visual Editor in the `enterComponent`
 * and `editedBlok` events. Here `space` arrives as a numeric id.
 */
export type BlockIframeData = {
    uid: string;
    id: string;
    space: number;
    name: string;
};
/**
 * Block metadata sent _to_ the Visual Editor in the `edit` action's `dataC`.
 * This shape is built from the DOM `_editable` comment (see `editable/parsing.ts`),
 * so `space` is a stringified id here — unlike the incoming {@link BlockIframeData}.
 */
export type EditableBlockData = {
    uid: string;
    id: string;
    space: string;
    name: string;
};
